import 'package:cerne/features/settings/presentation/pages/settings_placeholder_page.dart';
import 'package:cerne/features/splash/presentation/pages/splash_page.dart';
import 'package:cerne/features/vault/presentation/bloc/vault_bloc.dart';
import 'package:cerne/features/vault/presentation/pages/vault_page.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:go_router/go_router.dart';

/// Root [NavigatorState] key — exposed so the session-expired overlay
/// (`showDialog`) can raise itself over whichever screen is currently active,
/// regardless of `go_router`'s own internal navigator (research.md R3).
final GlobalKey<NavigatorState> rootNavigatorKey = GlobalKey<NavigatorState>();

final GoRouter appRouter = GoRouter(
  navigatorKey: rootNavigatorKey,
  initialLocation: AppRoutes.splash,
  routes: [
    GoRoute(
      path: AppRoutes.splash,
      builder: (context, state) => const SplashPage(),
    ),
    GoRoute(
      path: AppRoutes.login,
      builder: (context, state) => BlocProvider<AuthBloc>(
        create: (_) => getIt<AuthBloc>(),
        child: const LoginSignupPage(),
      ),
    ),
    GoRoute(
      path: AppRoutes.vault,
      builder: (context, state) => BlocProvider<VaultBloc>(
        create: (_) => getIt<VaultBloc>(),
        child: const VaultPage(mode: VaultMode.gatekeeper),
      ),
    ),
    GoRoute(
      path: AppRoutes.home,
      builder: (context, state) => const HomeChatShellPage(),
    ),
    GoRoute(
      path: AppRoutes.records,
      builder: (context, state) => const RecordsPlaceholderPage(),
    ),
    GoRoute(
      path: AppRoutes.settings,
      builder: (context, state) => const SettingsPlaceholderPage(),
    ),
  ],
);

import 'package:cerne/core/design_tokens.dart';
import 'package:cerne/core/di/service_locator.dart';
import 'package:cerne/features/capture/presentation/bloc/insertion_modal_bloc.dart';
import 'package:cerne/features/capture/presentation/pages/insertion_modal_page.dart';
import 'package:cerne/features/home/presentation/widgets/app_drawer.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';

/// Fixed dark-green header (☰ + "Cerne" wordmark) and an empty conversation
/// area, plus a composer bar that is rendered but fully disabled — no fake
/// messages, no RF04 wiring (FR-016; research.md R10). Scaffold's `drawer`
/// gives the ☰ icon its tap target for free (User Story 4).
class HomeChatShellPage extends StatelessWidget {
  const HomeChatShellPage({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: DesignTokens.colorSurfaceBg,
      drawer: const AppDrawer(),
      appBar: AppBar(
        backgroundColor: DesignTokens.colorPrimary,
        foregroundColor: DesignTokens.colorOnPrimary,
        title: Text(
          'Cerne',
          style: DesignTokens.textTitleLg.copyWith(
            color: DesignTokens.colorOnPrimary,
          ),
        ),
      ),
      body: Column(
        children: [
          const Expanded(child: SizedBox.expand()),
          _ComposerBar(),
        ],
      ),
    );
  }
}

void _openInsertionModal(BuildContext context) {
  showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    builder: (_) => BlocProvider(
      create: (_) => getIt<InsertionModalBloc>(),
      child: const InsertionModalPage(),
    ),
  );
}

class _ComposerBar extends StatelessWidget {
  const _ComposerBar();

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(DesignTokens.spacingMd),
      decoration: const BoxDecoration(
        color: DesignTokens.colorSurfaceElevated,
        border: Border(top: BorderSide(color: DesignTokens.colorBorder)),
      ),
      child: Row(
        children: [
          IconButton(
            onPressed: () => _openInsertionModal(context),
            icon: const Icon(Icons.add, color: DesignTokens.colorPrimary),
          ),
          Expanded(
            child: TextField(
              enabled: false,
              decoration: const InputDecoration(
                hintText: 'Escreva uma mensagem...',
              ),
            ),
          ),
          const SizedBox(width: DesignTokens.spacingSm),
          IconButton(
            onPressed: null,
            icon: const Icon(Icons.send, color: DesignTokens.colorTextSecondary),
          ),
        ],
      ),
    );
  }
}

