1	import 'dart:async';
2	
3	import 'package:cerne/features/capture/domain/entities/recognition_failure.dart';
4	import 'package:cerne/features/capture/domain/repositories/audio_capture_repository.dart';
5	import 'package:cerne/features/capture/domain/repositories/audio_transcription_repository.dart';
6	import 'package:cerne/features/capture/domain/repositories/photo_capture_repository.dart';
7	import 'package:cerne/features/capture/domain/usecases/confirm_entry_save_usecase.dart';
8	import 'package:cerne/features/capture/domain/usecases/recognize_photo_usecase.dart';
9	import 'package:cerne/features/capture/domain/usecases/save_text_entry_usecase.dart';
10	import 'package:cerne/features/capture/presentation/bloc/insertion_modal_event.dart';
11	import 'package:cerne/features/capture/presentation/bloc/insertion_modal_state.dart';
12	import 'package:cerne/features/entries/domain/entities/entry.dart';
13	import 'package:flutter_bloc/flutter_bloc.dart';
14	
15	const _offlineMessage = 'Sem conexão. Conecte-se à internet para salvar.';
16	const _noSpeechMessage = 'Não foi possível identificar fala no áudio.';
17	const _genericAudioMessage = 'Não foi possível transcrever';
18	const _noTextMessage = 'Não foi possível reconhecer o texto — tente outra foto.';
19	
20	/// The fixed placeholder sent as `content` for "Salvar só a foto"
21	/// (research.md R3) — a single `const` at this, its one call site.
22	const _photoNoTextPlaceholder = 'Foto registrada sem texto reconhecido.';
23	
24	/// One screen-scoped bloc for the whole Insertion Modal
25	/// (contracts/insertion-modal-bloc.md) — created fresh by `BlocProvider`
26	/// every time `showModalBottomSheet` opens the modal, which is what makes
27	/// FR-002's "reset every tab... each time the modal is freshly opened" true
28	/// without an explicit reset event.
29	class InsertionModalBloc
30	    extends Bloc<InsertionModalEvent, InsertionModalState> {
31	  InsertionModalBloc({
32	    required this._saveTextEntryUseCase,
33	    required this._audioCaptureRepository,
34	    required this._audioTranscriptionRepository,
35	    required this._confirmEntrySaveUseCase,
36	    required this._photoCaptureRepository,
37	    required this._recognizePhotoUseCase,
38	  }) : super(const InsertionModalTexto()) {
39	    on<TabSelected>(_onTabSelected);
40	    on<TextDraftChanged>(_onTextDraftChanged);
41	    on<SaveTextSubmitted>(_onSaveTextSubmitted);
42	    on<AudioStartRequested>(_onAudioStartRequested);
43	    on<AudioTimerTicked>(_onAudioTimerTicked);
44	    on<AudioStopRequested>(_onAudioStopRequested);
45	    on<AudioReviewTextChanged>(_onAudioReviewTextChanged);
46	    on<AudioSaveConfirmed>(_onAudioSaveConfirmed);
47	    on<PhotoSourceSelected>(_onPhotoSourceSelected);
48	    on<PhotoReviewTextChanged>(_onPhotoReviewTextChanged);
49	    on<PhotoSaveConfirmed>(_onPhotoSaveConfirmed);
50	    on<PhotoSaveWithoutTextRequested>(_onPhotoSaveWithoutTextRequested);
51	    on<RetryRequested>(_onRetryRequested);
52	    on<ModalClosed>(_onModalClosed);
53	  }
54	
55	  final SaveTextEntryUseCase _saveTextEntryUseCase;
56	  final AudioCaptureRepository _audioCaptureRepository;
57	  final AudioTranscriptionRepository _audioTranscriptionRepository;
58	  final ConfirmEntrySaveUseCase _confirmEntrySaveUseCase;
59	  final PhotoCaptureRepository _photoCaptureRepository;
60	  final RecognizePhotoUseCase _recognizePhotoUseCase;
61	
62	  final _closeController = StreamController<void>.broadcast();
63	
64	  /// A one-shot side effect, not a state (FR-011, contracts/
65	  /// insertion-modal-bloc.md) — `InsertionModalPage` listens to this to pop
66	  /// the sheet. There is nothing to render for "success", so it never
67	  /// becomes a dedicated `InsertionModalState` case.
68	  Stream<void> get closeRequests => _closeController.stream;
69	
70	  String _textDraft = '';
71	  String? _pendingAudioPath;
72	  String? _pendingImagePath;
73	  Timer? _audioTicker;
74	
75	  /// Guards against discarding the same recording twice when both the
76	  /// explicit `ModalClosed` handler and `close()`'s disposal-time fallback
77	  /// (for the swipe-down/tap-outside dismissal that bypasses `ModalClosed`)
78	  /// would otherwise race on the same still-recording state.
79	  bool _recordingDiscarded = false;
80	
81	  bool _isAudioAbandonable(InsertionModalState state) =>
82	      state is InsertionModalAudioProcessing ||
83	      state is InsertionModalAudioTranscribed ||
84	      state is InsertionModalAudioSaving ||
85	      state is InsertionModalAudioSaveFailure ||
86	      state is InsertionModalAudioFailure;
87	
88	  bool _isFotoAbandonable(InsertionModalState state) =>
89	      state is InsertionModalFotoProcessing ||
90	      state is InsertionModalFotoReconhecido ||
91	      state is InsertionModalFotoSaving ||
92	      state is InsertionModalFotoSaveFailure ||
93	      state is InsertionModalFotoFailure;
94	
95	  Future<void> _onTabSelected(
96	    TabSelected event,
97	    Emitter<InsertionModalState> emit,
98	  ) async {
99	    final current = state;
100	    if (current is InsertionModalAudioRecording) {
101	      // Switching away mid-recording discards it (Edge Cases) — nothing
102	      // from an abandoned capture may survive (FR-011).
103	      _audioCaptureRepository.discard();
104	      _recordingDiscarded = true;
105	      _stopAudioTicker();
106	      _pendingAudioPath = null;
107	    } else if (_isAudioAbandonable(current)) {
108	      // Leaving any in-flight/reviewed/failed Áudio sub-state abandons the
109	      // held audio and any unsaved review edits (FR-011, data-model.md's
110	      // transition table).
111	      _pendingAudioPath = null;
112	    }
113	
114	    if (_isFotoAbandonable(current)) {
115	      _pendingImagePath = null;
116	    }
117	
118	    switch (event.tab) {
119	      case CaptureTab.texto:
120	        emit(InsertionModalTexto(text: _textDraft));
121	      case CaptureTab.audio:
122	        emit(const InsertionModalAudioIdle());
123	      case CaptureTab.foto:
124	        emit(const InsertionModalFotoCaptura());
125	    }
126	  }
127	
128	  Future<void> _onAudioStartRequested(
129	    AudioStartRequested event,
130	    Emitter<InsertionModalState> emit,
131	  ) async {
132	    if (state is! InsertionModalAudioIdle) return;
133	
134	    final hasPermission = await _audioCaptureRepository.hasPermission();
135	    if (!hasPermission) {
136	      emit(const InsertionModalAudioPermissionDenied());
137	      return;
138	    }
139	    await _audioCaptureRepository.start();
140	    _recordingDiscarded = false;
141	    emit(const InsertionModalAudioRecording(elapsed: Duration.zero));
142	    _startAudioTicker();
143	  }
144	
145	  void _startAudioTicker() {
146	    _audioTicker?.cancel();
147	    _audioTicker = Timer.periodic(
148	      const Duration(seconds: 1),
149	      (_) => add(const AudioTimerTicked()),
150	    );
151	  }
152	
153	  void _stopAudioTicker() {
154	    _audioTicker?.cancel();
155	    _audioTicker = null;
156	  }
157	
158	  void _onTextDraftChanged(
159	    TextDraftChanged event,
160	    Emitter<InsertionModalState> emit,
161	  ) {
162	    _textDraft = event.text;
163	    emit(InsertionModalTexto(text: event.text));
164	  }
165	
166	  void _onAudioTimerTicked(
167	    AudioTimerTicked event,
168	    Emitter<InsertionModalState> emit,
169	  ) {
170	    final current = state;
171	    if (current is InsertionModalAudioRecording) {
172	      emit(
173	        InsertionModalAudioRecording(
174	          elapsed: current.elapsed + const Duration(seconds: 1),
175	        ),
176	      );
177	    }
178	  }
179	
180	  Future<void> _onSaveTextSubmitted(
181	    SaveTextSubmitted event,
182	    Emitter<InsertionModalState> emit,
183	  ) async {
184	    final current = state;
185	    final text = switch (current) {
186	      InsertionModalTexto(text: final t) => t,
187	      InsertionModalTextoFailure(text: final t) => t,
188	      _ => null,
189	    };
190	    if (text == null || text.trim().isEmpty) return;
191	
192	    emit(InsertionModalTextoSaving(text));
193	    final result = await _saveTextEntryUseCase(text);
194	    result.match(
195	      (failure) => emit(
196	        InsertionModalTextoFailure(text: text, message: failure.message),
197	      ),
198	      (entry) => _completeSave(),
199	    );
200	  }
201	
202	  Future<void> _onAudioStopRequested(
203	    AudioStopRequested event,
204	    Emitter<InsertionModalState> emit,
205	  ) async {
206	    final current = state;
207	    if (current is! InsertionModalAudioRecording) return;
208	
209	    _stopAudioTicker();
210	    final duration = current.elapsed;
211	    final path = await _audioCaptureRepository.stop();
212	    _pendingAudioPath = path;
213	    // No connectivity gate (FR-001, research.md R1) — on-device
214	    // transcription must begin unconditionally on stop.
215	    emit(InsertionModalAudioProcessing(duration: duration));
216	    await _transcribeAudio(path, duration, emit);
217	  }
218	
219	  Future<void> _transcribeAudio(
220	    String audioFilePath,
221	    Duration duration,
222	    Emitter<InsertionModalState> emit,
223	  ) async {
224	    final result = await _audioTranscriptionRepository.transcribe(
225	      audioFilePath,
226	    );
227	
228	    // The user may have switched tabs/closed the modal while transcription
229	    // was running — discard a stale result outright (research.md R6,
230	    // FR-011/User Story 5).
231	    if (state is! InsertionModalAudioProcessing ||
232	        _pendingAudioPath != audioFilePath) {
233	      return;
234	    }
235	
236	    result.match(
237	      (failure) => emit(
238	        InsertionModalAudioFailure(
239	          duration: duration,
240	          message: _recognitionFailureMessage(failure),
241	        ),
242	      ),
243	      (text) =>
244	          emit(InsertionModalAudioTranscribed(text: text, duration: duration)),
245	    );
246	  }
247	
248	  String _recognitionFailureMessage(RecognitionFailure failure) =>
249	      switch (failure) {
250	        EmptyRecognitionResult() => _noSpeechMessage,
251	        TranscriptionError() => _genericAudioMessage,
252	      };
253	
254	  void _onAudioReviewTextChanged(
255	    AudioReviewTextChanged event,
256	    Emitter<InsertionModalState> emit,
257	  ) {
258	    final current = state;
259	    if (current is InsertionModalAudioTranscribed) {
260	      emit(
261	        InsertionModalAudioTranscribed(
262	          text: event.text,
263	          duration: current.duration,
264	        ),
265	      );
266	    } else if (current is InsertionModalAudioSaveFailure) {
267	      emit(
268	        InsertionModalAudioSaveFailure(
269	          text: event.text,
270	          duration: current.duration,
271	          message: current.message,
272	        ),
273	      );
274	    }
275	  }
276	
277	  Future<void> _onAudioSaveConfirmed(
278	    AudioSaveConfirmed event,
279	    Emitter<InsertionModalState> emit,
280	  ) async {
281	    final current = state;
282	    final (text, duration) = switch (current) {
283	      InsertionModalAudioTranscribed(text: final t, duration: final d) => (
284	        t,
285	        d,
286	      ),
287	      InsertionModalAudioSaveFailure(text: final t, duration: final d) => (
288	        t,
289	        d,
290	      ),
291	      _ => (null, null),
292	    };
293	    if (text == null || duration == null || text.trim().isEmpty) return;
294	
295	    emit(InsertionModalAudioSaving(text: text, duration: duration));
296	    final result = await _confirmEntrySaveUseCase(text, EntrySource.audio);
297	    result.match(
298	      (failure) => emit(
299	        InsertionModalAudioSaveFailure(
300	          text: text,
301	          duration: duration,
302	          message: _confirmSaveFailureMessage(failure),
303	        ),
304	      ),
305	      (entry) {
306	        _pendingAudioPath = null;
307	        _completeSave();
308	      },
309	    );
310	  }
311	
312	  Future<void> _onPhotoSourceSelected(
313	    PhotoSourceSelected event,
314	    Emitter<InsertionModalState> emit,
315	  ) async {
316	    final current = state;
317	    if (current is InsertionModalFotoProcessing ||
318	        current is InsertionModalFotoSaving) {
319	      return;
320	    }
321	
322	    String? path;
323	    try {
324	      path = await _photoCaptureRepository.pickImage(event.source);
325	    } catch (_) {
326	      emit(const InsertionModalFotoPermissionDenied());
327	      return;
328	    }
329	
330	    if (path == null) {
331	      emit(const InsertionModalFotoCaptura());
332	      return;
333	    }
334	
335	    _pendingImagePath = path;
336	    emit(InsertionModalFotoProcessing(imagePath: path));
337	    await _recognizePhoto(path, emit);
338	  }
339	
340	  Future<void> _recognizePhoto(
341	    String imageFilePath,
342	    Emitter<InsertionModalState> emit,
343	  ) async {
344	    final result = await _recognizePhotoUseCase(imageFilePath);
345	
346	    // Same stale-result guard as audio (research.md R6).
347	    if (state is! InsertionModalFotoProcessing ||
348	        _pendingImagePath != imageFilePath) {
349	      return;
350	    }
351	
352	    result.match(
353	      (failure) => emit(
354	        InsertionModalFotoFailure(
355	          imagePath: imageFilePath,
356	          message: _photoRecognitionFailureMessage(failure),
357	        ),
358	      ),
359	      // confidence read but never branched on (Clarification 3).
360	      (ocrResult) => emit(
361	        InsertionModalFotoReconhecido(
362	          imagePath: imageFilePath,
363	          text: ocrResult.text,
364	        ),
365	      ),
366	    );
367	  }
368	
369	  // Every failed OCR call — not just "no text found" — shows the same
370	  // "Foto — Erro" copy (FR-007: "If the OCR call fails (including a
371	  // no-usable-text result)..."), never the raw backend `message`.
372	  String _photoRecognitionFailureMessage(
373	    PhotoRecognitionAttemptFailure failure,
374	  ) => switch (failure) {
375	    PhotoRecognitionOffline() => _offlineMessage,
376	    PhotoRecognitionCallFailed() => _noTextMessage,
377	  };
378	
379	  void _onPhotoReviewTextChanged(
380	    PhotoReviewTextChanged event,
381	    Emitter<InsertionModalState> emit,
382	  ) {
383	    final current = state;
384	    if (current is InsertionModalFotoReconhecido) {
385	      emit(
386	        InsertionModalFotoReconhecido(
387	          imagePath: current.imagePath,
388	          text: event.text,
389	        ),
390	      );
391	    } else if (current is InsertionModalFotoSaveFailure) {
392	      emit(
393	        InsertionModalFotoSaveFailure(
394	          imagePath: current.imagePath,
395	          text: event.text,
396	          message: current.message,
397	        ),
398	      );
399	    }
400	  }
401	
402	  Future<void> _onPhotoSaveConfirmed(
403	    PhotoSaveConfirmed event,
404	    Emitter<InsertionModalState> emit,
405	  ) async {
406	    final current = state;
407	    final (imagePath, text) = switch (current) {
408	      InsertionModalFotoReconhecido(imagePath: final p, text: final t) => (
409	        p,
410	        t,
411	      ),
412	      InsertionModalFotoSaveFailure(imagePath: final p, text: final t) => (
413	        p,
414	        t,
415	      ),
416	      _ => (null, null),
417	    };
418	    if (imagePath == null || text == null || text.trim().isEmpty) return;
419	
420	    await _confirmPhotoSave(imagePath, text, emit);
421	  }
422	
423	  Future<void> _onPhotoSaveWithoutTextRequested(
424	    PhotoSaveWithoutTextRequested event,
425	    Emitter<InsertionModalState> emit,
426	  ) async {
427	    final current = state;
428	    if (current is! InsertionModalFotoFailure) return;
429	
430	    // No further OCR call for this capture (FR-008) — saves immediately
431	    // with the fixed placeholder.
432	    await _confirmPhotoSave(current.imagePath, _photoNoTextPlaceholder, emit);
433	  }
434	
435	  Future<void> _confirmPhotoSave(
436	    String imagePath,
437	    String text,
438	    Emitter<InsertionModalState> emit,
439	  ) async {
440	    emit(InsertionModalFotoSaving(imagePath: imagePath, text: text));
441	    final result = await _confirmEntrySaveUseCase(text, EntrySource.photo);
442	    result.match(
443	      (failure) => emit(
444	        InsertionModalFotoSaveFailure(
445	          imagePath: imagePath,
446	          text: text,
447	          message: _confirmSaveFailureMessage(failure),
448	        ),
449	      ),
450	      (entry) {
451	        _pendingImagePath = null;
452	        _completeSave();
453	      },
454	    );
455	  }
456	
457	  String _confirmSaveFailureMessage(ConfirmEntrySaveFailure failure) =>
458	      switch (failure) {
459	        ConfirmEntrySaveOffline() => _offlineMessage,
460	        ConfirmEntrySaveCreationFailed(failure: final f) => f.message,
461	      };
462	
463	  Future<void> _onRetryRequested(
464	    RetryRequested event,
465	    Emitter<InsertionModalState> emit,
466	  ) async {
467	    final current = state;
468	    final audioPath = _pendingAudioPath;
469	    final imagePath = _pendingImagePath;
470	    if (current is InsertionModalAudioFailure && audioPath != null) {
471	      final duration = current.duration;
472	      emit(InsertionModalAudioProcessing(duration: duration));
473	      await _transcribeAudio(audioPath, duration, emit);
474	    } else if (current is InsertionModalFotoFailure && imagePath != null) {
475	      emit(InsertionModalFotoProcessing(imagePath: imagePath));
476	      await _recognizePhoto(imagePath, emit);
477	    }
478	  }
479	
480	  void _onModalClosed(ModalClosed event, Emitter<InsertionModalState> emit) {
481	    if (state is InsertionModalAudioRecording) {
482	      _audioCaptureRepository.discard();
483	      _recordingDiscarded = true;
484	      _stopAudioTicker();
485	    }
486	    // Unconditionally clears every held capture, regardless of which
487	    // Áudio/Foto sub-state is active when the modal closes (FR-011).
488	    _pendingAudioPath = null;
489	    _pendingImagePath = null;
490	  }
491	
492	  void _completeSave() {
493	    if (!_closeController.isClosed) {
494	      _closeController.add(null);
495	    }
496	  }
497	
498	  @override
499	  Future<void> close() {
500	    if (state is InsertionModalAudioRecording && !_recordingDiscarded) {
501	      // `showModalBottomSheet`'s default swipe-down/tap-outside dismissal
502	      // bypasses `ModalClosed` entirely, so this is the only place that
503	      // reliably catches a still-recording mic at disposal time (FR-011).
504	      _audioCaptureRepository.discard();
