import 'package:cerne/features/entries/domain/entities/entry.dart';
import 'package:equatable/equatable.dart';

const _monthNames = [
  'janeiro',
  'fevereiro',
  'março',
  'abril',
  'maio',
  'junho',
  'julho',
  'agosto',
  'setembro',
  'outubro',
  'novembro',
  'dezembro',
];

/// One date-heading bucket of entries (FR-002). `entries` preserves
/// whatever order the input list already had — `DateGrouper.group` never
/// re-sorts within or across groups.
class DateGroup extends Equatable {
  const DateGroup({required this.label, required this.entries});

  /// "Hoje" | "Ontem" | "{day} de {monthName}" (research.md R9).
  final String label;
  final List<Entry> entries;

  @override
  List<Object?> get props => [label, entries];
}

/// Buckets an already newest-to-oldest-sorted entry list by calendar day
/// (data-model.md). Only buckets — never sorts.
class DateGrouper {
  const DateGrouper._();

  static List<DateGroup> group(List<Entry> entries, {DateTime? now}) {
    final today = (now ?? DateTime.now()).toLocal();
    final groups = <DateGroup>[];

    String? currentLabel;
    List<Entry> currentEntries = [];

    void flush() {
      if (currentLabel != null) {
        groups.add(DateGroup(label: currentLabel, entries: currentEntries));
      }
    }

    for (final entry in entries) {
      final label = _labelFor(entry.occurredAt.toLocal(), today);
      if (label != currentLabel) {
        flush();
        currentLabel = label;
        currentEntries = [];
      }
      currentEntries.add(entry);
    }
    flush();

    return groups;
  }

  static String _labelFor(DateTime occurredAt, DateTime today) {
    final occurredDay = DateTime(occurredAt.year, occurredAt.month, occurredAt.day);
    final todayDay = DateTime(today.year, today.month, today.day);
    final difference = todayDay.difference(occurredDay).inDays;

    if (difference == 0) return 'Hoje';
    if (difference == 1) return 'Ontem';
    return '${occurredAt.day} de ${_monthNames[occurredAt.month - 1]}';
  }
}

