      await client.call(
        'records',
        method: 'GET',
        pathSegments: ['123', 'items'],
      );

      verify(
        () => dio.request<Map<String, dynamic>>(
          '$baseUrl/records/123/items',
          data: any(named: 'data'),
          options: any(named: 'options'),
        ),
      ).called(1);
    });
