        queryParameters: {'cursor': 'abc'},
      );

      verify(
        () => dio.request<Map<String, dynamic>>(
          any(),
          data: any(named: 'data'),
          queryParameters: {'cursor': 'abc'},
          options: any(named: 'options'),
        ),
      ).called(1);
    });

