    stubCall(const Right({'unexpected': true}));

    final result = await dataSource.create(content: 'hello', source: EntrySource.manual);

    expect(result.isLeft(), isTrue);
    expect(result.getLeft().toNullable(), isA<ValidationFailure>());
  });
}

