            child: TextField(
              enabled: false,
              decoration: const InputDecoration(hintText: 'Buscar nos registros...'),
            ),
          ),
          const SizedBox(width: DesignTokens.spacingSm),
          // Inert placeholder — no filter sheet in this unit (FR-008).
          IconButton(onPressed: null, icon: const Icon(Icons.filter_list)),
        ],
      ),
    );
  }
}

